def test_head_object_404_with_policy_prefix():
        client = get_client()
        bucket = get_new_bucket(client)

        policy = json.dumps({
            "Version": "2012-10-17",
            "Statement": [{
                "Effect": "Allow",
                "Principal": {"AWS": "*"},
                "Action": "s3:ListBucket",
                "Resource": f"arn:aws:s3:::{bucket}",
                "Condition": {
                    "StringLike": {
                        "s3:prefix": "public/*"
                    }
                }
            }]
        })
        client.put_bucket_policy(Bucket=bucket, Policy=policy)

        alt_client = get_alt_client()
        # expect 404 NoSuchKey for names that match the s3:prefix
        e = assert_raises(ClientError, alt_client.head_object, Bucket=bucket, Key='public/object')
>       assert 404 == _get_status(e.response)
E       AssertionError: assert 404 == 403
E        +  where 403 = _get_status({'Error': {'Code': '403', 'Message': 'Forbidden'}, 'ResponseMetadata': {'RequestId': '260496C11BE84BCF8C543E83D967A047...quest-id': '260496C11BE84BCF8C543E83D967A047', 'content-length': '247', 'date': 'Sat, 03 Oct 2026 11:19:36 GMT'}, ...}})
E        +    where {'Error': {'Code': '403', 'Message': 'Forbidden'}, 'ResponseMetadata': {'RequestId': '260496C11BE84BCF8C543E83D967A047...quest-id': '260496C11BE84BCF8C543E83D967A047', 'content-length': '247', 'date': 'Sat, 03 Oct 2026 11:19:36 GMT'}, ...}} = ClientError('An error occurred (403) when calling the HeadObject operation: Forbidden').response

